+        .map(|i| {
+            Point3::new(
+                [b.min.x, b.max.x][(i >> 2) & 1],
+                [b.min.y, b.max.y][(i >> 1) & 1],
+                [b.min.z, b.max.z][i & 1],
+            )
+        })
+        .collect();
+    for t in chain.segments.iter().filter_map(|s| s.turn.as_ref()) {
+        for p in &mut pts {
+            *p = t.apply(*p);
+        }
+    }
