+        stock_to_leave: 0.0,
+        clearance_z: Height::fixed(12.0),
+        retract_z: Height::fixed(8.0),
+        top_z: Height::fixed(5.0),
+        bottom_z: Height::fixed(0.0),
+        stepdown: 2.5,
+        feed: 800.0,
+        plunge_feed: 200.0,
+        climb: true,
+        side: Side::Auto,
+        lead: Lead::None,
+        tolerance: 0.01,
